// Each item: { str, transform: [scaleX, skewY, skewX, scaleY, x, y], ... }
const lines = [];
for (const it of tc.items) {
  const [, , , , x, y] = it.transform;
  lines.push({ text: it.str, x, y });
}
// Then: cluster by y into lines, sort top-to-bottom, split columns by x-gaps.

// Dehyphenate: join line-break splits, preserve real compounds
function dehyphenate(text) {
  return text.replace(/([A-Za-z])-[ \t]*\n[ \t]*([a-z])/g, "$1$2");
}
// 'cus-\ntomer' -> 'customer'   (rejoined: lowercase continuation)
// 'state-of-\nthe-art' stays? 'e-\nt' + lowercase 't' rejoins to 'the' —
// correct here! Real danger is 'well-\nKnown' (capital K: preserved).

// Furniture stripper: repetition + position, never content blacklists
function stripFurniture(pages) {
  // pages: array of arrays of { text, y, pageHeight }
  const seen = new Map();
  for (const lines of pages)
    for (const l of lines) {
      const key = l.text.replace(/\d+/g, "#").trim();
      seen.set(key, (seen.get(key) || 0) + 1);
    }
  return pages.map((lines) =>
    lines.filter((l) => {
      const key = l.text.replace(/\d+/g, "#").trim();
      const edge = l.y < l.pageHeight * 0.1 || l.y > l.pageHeight * 0.9;
      return !(seen.get(key) >= 3 && edge); // repeated + marginal = furniture
    })
  );
}

